  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #121a2f;
      --panel-2: #18233d;
      --text: #e8eefc;
      --muted: #9eb0d1;
      --border: rgba(150, 171, 220, 0.18);
      --accent: #7c9cff;
      --accent-2: #58d1c9;
      --success: #53d18b;
      --danger: #ff7a90;
      --shadow: 0 18px 50px rgba(0, 0, 0, 0.35);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.16), transparent 34%),
        linear-gradient(180deg, #09101f 0%, var(--bg) 100%);
      color: var(--text);
      min-height: 100vh;
      padding: 32px 16px;
    }

    .quiz-shell {
      width: min(860px, 100%);
      margin: 0 auto;
      background: rgba(18, 26, 47, 0.9);
      border: 1px solid var(--border);
      border-radius: 24px;
      box-shadow: var(--shadow);
      overflow: hidden;
      backdrop-filter: blur(10px);
    }

    .quiz-header {
      padding: 28px 28px 20px;
      background: linear-gradient(180deg, rgba(124, 156, 255, 0.12), transparent);
      border-bottom: 1px solid var(--border);
    }

    h1 {
      margin: 0 0 10px;
      font-size: clamp(1.7rem, 3vw, 2.5rem);
      line-height: 1.1;
    }

    .subtitle {
      margin: 0;
      color: var(--muted);
      max-width: 60ch;
    }

