      padding: 8px 28px 28px;
    }

    .form-field {
      margin-top: 20px;
      padding: 20px;
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0.01));
      border: 1px solid var(--border);
      border-radius: 18px;
    }

    .question-title {
      display: block;
      font-size: 1.08rem;
      font-weight: 700;
      margin-bottom: 10px;
    }

    .help-text {
      margin: -2px 0 16px;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .choices {
      display: grid;
      gap: 12px;
    }

    .choice {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      padding: 14px 16px;
      background: rgba(10, 15, 28, 0.7);
      border: 1px solid rgba(150, 171, 220, 0.14);
      border-radius: 14px;
      transition: border-color 160ms ease, transform 160ms ease, background-color 160ms ease;
    }

    .choice:hover {
      transform: translateY(-1px);
      border-color: rgba(124, 156, 255, 0.42);
      background: rgba(16, 23, 40, 0.9);
    }

    .choice input {
      width: 18px;
      height: 18px;
      margin-top: 2px;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .choice span {
      line-height: 1.45;
    }

    .actions {
      display: flex;
      gap: 14px;
      align-items: center;
      margin-top: 22px;
      flex-wrap: wrap;
