    .result {
      min-height: 1.5em;
      color: var(--muted);
      font-weight: 600;
    }

    .result.success {
      color: var(--success);
    }

    .result.error {
      color: var(--danger);
    }
  </style>
</head>
<body>
  <main class="quiz-shell">
