          <label class="choice"><input type="checkbox" name="q1" value="Ruby" data-correct="true" /><span>Ruby</span></label>
        </div>
      </div>

      <div class="form-field">
        <label class="question-title">2. Which of these are compiled languages?</label>
        <div class="choices" role="group" aria-label="Question 2">
          <label class="choice"><input type="checkbox" name="q2" value="C" data-correct="true" /><span>C</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="Go" data-correct="true" /><span>Go</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="PHP" data-correct="false" /><span>PHP</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="Rust" data-correct="true" /><span>Rust</span></label>
        </div>
      </div>

      <div class="form-field">
        <label class="question-title">3. Which of these are language families or paradigms?</label>
        <div class="choices" role="group" aria-label="Question 3">
          <label class="choice"><input type="checkbox" name="q3" value="Functional programming" data-correct="true" /><span>Functional programming</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="Object-oriented programming" data-correct="true" /><span>Object-oriented programming</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="SQL" data-correct="false" /><span>SQL</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="Procedural programming" data-correct="true" /><span>Procedural programming</span></label>
        </div>
      </div>

      <div class="actions">
        <button type="submit">Submit quiz</button>
        <p class="result" id="result" aria-live="polite"></p>
      </div>
    </form>
