   <title>Computer Languages Quiz</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1020;
       --panel: #121a2f;
       --panel-2: #18233d;
       --text: #e8eefc;
       --muted: #9eb0d1;
       --border: rgba(150, 171, 220, 0.18);
