       background:
         radial-gradient(circle at top, rgba(124, 156, 255, 0.16), transparent 34%),
         linear-gradient(180deg, #09101f 0%, var(--bg) 100%);
       color: var(--text);
       min-height: 100vh;
       padding: 32px 16px;
     }

     .quiz-shell {
       width: min(860px, 100%);
