     .subtitle {
       margin: 0;
       color: var(--muted);
       max-width: 60ch;
     }

     form {
       padding: 8px 28px 28px;
     }

     .form-field {
       margin-top: 20px;
       padding: 20px;
       background: linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0.01));
       border: 1px solid var(--border);
       border-radius: 18px;
     }

     .question-title {
       display: block;
       font-size: 1.08rem;
       font-weight: 700;
       margin-bottom: 10px;
     }

     .help-text {
       margin: -2px 0 16px;
