 </head>
 <body>
   <main class="quiz-shell">
     <header class="quiz-header">
       <h1>Computer Languages Quiz</h1>
       <p class="subtitle">Choose all answers that apply for each question, then submit to see your score.</p>
     </header>

     <form id="quiz-form" novalidate>
       <div class="form-field">
         <h2 class="question-title" id="q1-title">1. Which of these are programming languages?</h2>
         <p class="help-text">Select every option that is a language used to write code.</p>
         <div class="choices" role="group" aria-labelledby="q1-title">
           <label class="choice"><input type="checkbox" name="q1" value="Python" data-correct="true" id="q1-1" /><span>Python</span></label>
           <label class="choice"><input type="checkbox" name="q1" value="HTML" data-correct="false" /><span>HTML</span></label>
           <label class="choice"><input type="checkbox" name="q1" value="JavaScript" data-correct="true" /><span>JavaScript</span></label>
           <label class="choice"><input type="checkbox" name="q1" value="Ruby" data-correct="true" /><span>Ruby</span></label>
         </div>
       </div>

       <div class="form-field">
         <h2 class="question-title" id="q2-title">2. Which of these are compiled languages?</h2>
         <div class="choices" role="group" aria-labelledby="q2-title">
           <label class="choice"><input type="checkbox" name="q2" value="C" data-correct="true" /><span>C</span></label>
           <label class="choice"><input type="checkbox" name="q2" value="Go" data-correct="true" /><span>Go</span></label>
           <label class="choice"><input type="checkbox" name="q2" value="PHP" data-correct="false" /><span>PHP</span></label>
           <label class="choice"><input type="checkbox" name="q2" value="Rust" data-correct="true" /><span>Rust</span></label>
         </div>
       </div>

       <div class="form-field">
         <h2 class="question-title" id="q3-title">3. Which of these are language families or paradigms?</h2>
         <div class="choices" role="group" aria-labelledby="q3-title">
           <label class="choice"><input type="checkbox" name="q3" value="Functional programming" data-correct="true" /><span>Functional programming</span></label>
           <label class="choice"><input type="checkbox" name="q3" value="Object-oriented programming" data-correct="true" /><span>Object-oriented programming</span></label>
           <label class="choice"><input type="checkbox" name="q3" value="SQL" data-correct="false" /><span>SQL</span></label>
           <label class="choice"><input type="checkbox" name="q3" value="Procedural programming" data-correct="true" /><span>Procedural programming</span></label>
         </div>
       </div>

       <div class="actions">
         <button type="submit">Submit quiz</button>
         <p class="result" id="result" aria-live="polite"></p>
       </div>
     </form>
   </main>

   <script>
     const form = document.getElementById("quiz-form");
     const result = document.getElementById("result");
     const questions = ["q1", "q2", "q3"];

     function getSelectedValues(name) {
       return Array.from(form.querySelectorAll(`input[name="${name}"]:checked`)).map((input) => input.value);
     }

     function getCorrectValues(name) {
       return Array.from(form.querySelectorAll(`input[name="${name}"]`))
         .filter((input) => input.dataset.correct === "true")
         .map((input) => input.value);
     }

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       let score = 0;

       questions.forEach((name) => {
         const selected = getSelectedValues(name).sort();
         const correct = getCorrectValues(name).sort();
         if (selected.length === correct.length && selected.every((value, index) => value === correct[index])) {
           score += 1;
         }
       });

       result.className = `result ${score === questions.length ? "success" : "error"}`;
       result.textContent = `You got ${score} out of ${questions.length} correct.`;
     });
   </script>
 </body>
